examples.setupTemplate:
val scope = rememberCoroutineScope()
var email by rememberSaveable { mutableStateOf({{email}}) }
var password by remember { mutableStateOf("") }
var keepSignedIn by rememberSaveable { mutableStateOf({{keepSignedIn}}) }
var emailError by remember { mutableStateOf<String?>(null) }
var passwordError by remember { mutableStateOf<String?>(null) }
var formError by remember { mutableStateOf<String?>(null) }
var signingIn by remember { mutableStateOf(false) }
val signIn = {
    val address = email.trim()
    emailError = if ("@" in address && "." in address) null else "Enter an email address like name@example.com."
    passwordError = if (password.isEmpty()) "Enter your password." else null
    if (emailError == null && passwordError == null) {
        signingIn = true
        scope.launch {
            // The app's request. A refused sign-in sets formError.
            signingIn = false
        }
    }
}

